const inventario = $('SELECT Inventario Completo').all().map(i => i.json);
const alertas = $('SELECT Alertas Semana').all().map(a => a.json);
const fecha = new Date().toISOString().split('T')[0];

// Obtener resumen de salidas de la semana mediante los movimientos
const salidaSemana = inventario; // placeholder para mantener estructura

// === CSV ===
const csvHeader = 'SKU,Nombre,Categoria,Stock Actual,Stock Minimo,Fecha Vencimiento,Estado\n';
const csvRows = inventario.map(p =>
  `"${p.sku}","${p.nombre}","${p.categoria}",${p.stock_actual},${p.stock_minimo},"${p.fecha_vencimiento ?? 'N/A'}","${p.estado}"`
).join('\n');
const csvContent = csvHeader + csvRows;

// === HTML ===
const alertasHTML = alertas.map(a =>
  `<tr style="background:${a.nivel === 'CRITICAL' ? '#fee2e2' : a.nivel === 'WARNING' ? '#fef9c3' : '#f0fdf4'}">
    <td>${a.tipo}</td><td>${a.nivel}</td><td>${a.sku ?? '-'}</td>
    <td>${a.mensaje}</td><td>${a.resuelta ? '✅' : '❌'}</td>
    <td>${a.created_at?.split('T')[0] ?? ''}</td>
  </tr>`
).join('');

const inventarioHTML = inventario.map(p =>
  `<tr style="background:${p.estado === 'STOCK_BAJO' ? '#fee2e2' : p.estado === 'VENCIMIENTO_PROXIMO' ? '#fef9c3' : 'white'}">
    <td>${p.sku}</td><td>${p.nombre}</td><td>${p.categoria}</td>
    <td>${p.stock_actual}</td><td>${p.stock_minimo}</td>
    <td>${p.fecha_vencimiento ?? 'N/A'}</td><td><b>${p.estado}</b></td>
  </tr>`
).join('');

const htmlContent = `<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><title>Reporte Inventario - ${fecha}</title>
<style>body{font-family:Arial,sans-serif;padding:20px}h1{color:#1e3a5f}table{border-collapse:collapse;width:100%;margin-bottom:24px}th{background:#1e3a5f;color:white;padding:8px;text-align:left}td{border:1px solid #ddd;padding:6px}</style>
</head><body>
<h1>📦 Reporte Semanal de Inventario</h1>
<p>Generado: ${new Date().toLocaleString('es-GT')} | Productos: ${inventario.length} | Alertas semana: ${alertas.length}</p>
<h2>📊 Estado del Inventario</h2>
<table><tr><th>SKU</th><th>Nombre</th><th>Categoría</th><th>Stock Actual</th><th>Stock Mínimo</th><th>Vencimiento</th><th>Estado</th></tr>
${inventarioHTML}</table>
<h2>🔔 Alertas de la Semana</h2>
<table><tr><th>Tipo</th><th>Nivel</th><th>SKU</th><th>Mensaje</th><th>Resuelta</th><th>Fecha</th></tr>
${alertasHTML || '<tr><td colspan="6">Sin alertas esta semana</td></tr>'}</table>
</body></html>`;

// === TXT ===
const txtContent = `=== REPORTE SEMANAL DE INVENTARIO ===
Fecha: ${fecha}
Total productos activos: ${inventario.length}
Alertas generadas esta semana: ${alertas.length}

PRODUCTOS CON PROBLEMAS:
${
  inventario.filter(p => p.estado !== 'OK')
    .map(p => `  - [${p.estado}] ${p.nombre} (${p.sku}) Stock: ${p.stock_actual}`)
    .join('\n') || '  Ninguno'
}

Reporte completo: /data/reports/reporte_inventario_${fecha}.html
`;

return [
  { json: { tipo: 'csv', contenido: csvContent, archivo: `reporte_inventario_${fecha}.csv` } },
  { json: { tipo: 'html', contenido: htmlContent, archivo: `reporte_inventario_${fecha}.html` } },
  { json: { tipo: 'txt', contenido: txtContent, archivo: `notificacion_reporte_${fecha}.txt` } }
];

const item = $input.item.json;
const encoder = new TextEncoder();
const bytes = encoder.encode(item.contenido);
const mimeTypes = { csv: 'text/csv', html: 'text/html', txt: 'text/plain' };
return [{
  json: {
    carpeta: item.tipo === 'txt' ? '/data/outbox' : '/data/reports',
    archivo: item.archivo,
    tipo: item.tipo
  },
  binary: {
    data: {
      data: Buffer.from(bytes).toString('base64'),
      mimeType: mimeTypes[item.tipo] ?? 'text/plain',
      fileName: item.archivo,
      fileExtension: item.tipo
    }
  }
}];
